/* HEXA BATTLEGROUNDS setup — PART 49 OF 57. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-morse-11', 'morse', 'mission', 'Radio Morse', 'decoding', 2, array['any','transmission','access','gate','observation','terrace']::text[], 'A Morse signal came over the squad radio. Scout copied it; Decoder holds letters A–M and Intel letters N–Z. Decode the word.', '{"scout":{"title":"Intercepted signal","body":"·−·   /   −−−   /   ··−   /   −   /   ·\n\n(5 letters, “/” separates letters)","mono":true,"big":true},"decoder":{"title":"Codebook A–M","body":"A ·−\nB −···\nC −·−·\nD −··\nE ·\nF ··−·\nG −−·\nH ····\nI ··\nJ ·−−−\nK −·−\nL ·−··\nM −−","mono":true},"intel":{"title":"Codebook N–Z","body":"N −·\nO −−−\nP ·−−·\nQ −−·−\nR ·−·\nS ···\nT −\nU ··−\nV ···−\nW ·−−\nX −··−\nY −·−−\nZ −−··","mono":true}}'::jsonb, '[{"label":"Decoded word","accept":["ROUTE"]}]'::jsonb, false, 3, 200, '· is a short beep, − is a long beep. Read one letter at a time and ask both codebooks.', '·−·=R −−−=O ··−=U −=T ·=E', null, 25, 'published'), ('mission-scramble-0', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"A P P L T O\n\nClue: portable computer\n\n(6 letters · starts with L)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"E E S R R V\n\nClue: machine that serves requests\n\n(6 letters · starts with S)","mono":true,"big":false},"intel":{"title":"Word 3","body":"R E S R B O W\n\nClue: opens web pages\n\n(7 letters · starts with B)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["LAPTOP"]},{"label":"Word 2 (Decoder)","accept":["SERVER"]},{"label":"Word 3 (Intel)","accept":["BROWSER"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: LA…, SE…, BR…', 'LAPTOP: unscrambled (portable computer) | SERVER: unscrambled (machine that serves requests) | BROWSER: unscrambled (opens web pages)', null, 25, 'published'), ('mission-scramble-1', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"O R D B A Y K E\n\nClue: you type on it\n\n(8 letters · starts with K)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"I N O R T M O\n\nClue: a screen\n\n(7 letters · starts with M)","mono":true,"big":false},"intel":{"title":"Word 3","body":"E T I R P R N\n\nClue: puts pages on paper\n\n(7 letters · starts with P)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["KEYBOARD"]},{"label":"Word 2 (Decoder)","accept":["MONITOR"]},{"label":"Word 3 (Intel)","accept":["PRINTER"]}]'::jsonb, false, 3, 200, 'Say the clue out loud first — it narrows the word down. Answers start with: KE…, MO…, PR…', 'KEYBOARD: unscrambled (you type on it) | MONITOR: unscrambled (a screen) | PRINTER: unscrambled (puts pages on paper)', null, 25, 'published'), ('mission-scramble-2', 'scramble', 'mission', 'Word Scramble', 'words', 1, array['any','office','learning','helpdesk','hr','stg']::text[], 'Each teammate holds one scrambled office or tech word. Unscramble all three.', '{"scout":{"title":"Word 1","body":"K W N R T E O\n\nClue: connected computers\n\n(7 letters · starts with N)","mono":true,"big":false},"decoder":{"title":"Word 2","body":"S D R W P S O A\n\nClue: keep it secret\n\n(8 letters · starts with P)","mono":true,"big":false},"intel":{"title":"Word 3","body":"I E N M T G E\n\nClue: calendar invite\n\n(7 letters · starts with M)","mono":true,"big":false}}'::jsonb, '[{"label":"Word 1 (Scout)","accept":["NETWORK"]},{"label":"Word 